package finance.bank;
import java.util.UUID;
public final class CentralBankLiquidityLoan {private final UUID id,bankId;private final long principal,issueDay,maturityDay;private final int rateBps;private CentralBankLoanStatus status;public CentralBankLiquidityLoan(UUID id,UUID bankId,long principal,int rateBps,long issueDay,long maturityDay,CentralBankLoanStatus status){if(id==null||bankId==null||principal<=0||rateBps<0||issueDay<0||maturityDay<=issueDay||status==null)throw new IllegalArgumentException();this.id=id;this.bankId=bankId;this.principal=principal;this.rateBps=rateBps;this.issueDay=issueDay;this.maturityDay=maturityDay;this.status=status;}public UUID id(){return id;}public UUID bankId(){return bankId;}public long principal(){return principal;}public int rateBasisPoints(){return rateBps;}public long issueDay(){return issueDay;}public long maturityDay(){return maturityDay;}public CentralBankLoanStatus status(){return status;}void setStatus(CentralBankLoanStatus s){status=s;}}
